// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');
import { Star } from "@remotion/shapes";

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: antonFamily } = loadAnton();



export type InflectionPointsProps = Record<string, any>;

// Internal fallback identifier mapping


const InflectionPoints: React.FC<InflectionPointsProps> = ({
  backgroundColor = "#0d0d0c",
  transparentBackground = false,
  durationInSeconds = 8,
  titleText = "INFLECTION POINTS",
  starCount = 5,
  starColor = "#fadb14",
  starOutlineColor = "#ffe58f",
  lineColor = "#ffffff",
  zoomIntensity = 3.5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 1. Camera Zoom Timeline
  const startZoomFrame = Math.floor(totalFrames * 0.65);
  const endZoomFrame = Math.floor(totalFrames * 0.95);

  const cameraScale = interpolate(
    frame,
    [startZoomFrame, endZoomFrame],
    [1, zoomIntensity],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.bezier(0.25, 1, 0.5, 1),
    }
  );

  // Fade out ambient particles as we zoom into the title
  const zoomFadeProgress = interpolate(
    frame,
    [startZoomFrame, startZoomFrame + Math.min(30, totalFrames * 0.15)],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const elementsOpacity = 1 - zoomFadeProgress;

  // 2. Title Entrance Timeline (0% to 18% of duration)
  const titleIntroEnd = Math.floor(totalFrames * 0.18);
  const titleFade = interpolate(frame, [0, Math.floor(totalFrames * 0.12)], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const titleScale = interpolate(frame, [0, titleIntroEnd], [1.2, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const titleTracking = interpolate(frame, [0, titleIntroEnd], [0.25, 0.05], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });

  // 3. Glowing Separator Flare (starts slightly after title starts)
  const flareStart = Math.floor(totalFrames * 0.08);
  const flareEnd = Math.floor(totalFrames * 0.22);
  const separatorScaleX = interpolate(frame, [flareStart, flareEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const separatorOpacity = interpolate(frame, [flareStart, flareStart + 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 4. Connecting Line Timeline
  const lineStart = Math.floor(totalFrames * 0.12);
  const lineEnd = Math.floor(totalFrames * 0.52);
  const lineScaleX = interpolate(frame, [lineStart, lineEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 1, 0.5, 1),
  });

  // Ambient back-glow breathing animation
  const ambientBreathe = interpolate(Math.sin(frame * 0.05), [-1, 1], [0.15, 0.25]);

  // Deterministic Gold Particles for rich background production value
  const particles = Array.from({ length: 25 }).map((_, i) => {
    const seed = i * 153.25;
    const randomX = random(`x-${seed}`) * 100;
    const randomY = random(`y-${seed}`) * 100;
    const size = random(`size-${seed}`) * 12 + 4;
    const driftSpeed = random(`drift-${seed}`) * 0.4 + 0.15;
    const opacityBase = random(`op-${seed}`) * 0.3 + 0.15;
    return { randomX, randomY, size, driftSpeed, opacityBase };
  });

  // Line coordinates
  const lineWidthPercent = 75;
  const lineLeftPercent = 12.5;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Cinematic Golden Particle Field */}
      {particles.map((p, i) => {
        const driftedY = (p.randomY - frame * p.driftSpeed) % 100;
        const finalY = driftedY < 0 ? driftedY + 100 : driftedY;
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: `${p.randomX}%`,
              top: `${finalY}%`,
              width: p.size,
              height: p.size,
              borderRadius: "50%",
              background: `radial-gradient(circle, #ffea00dd 0%, transparent 70%)`,
              opacity: p.opacityBase * elementsOpacity,
              mixBlendMode: "screen",
              pointerEvents: "none",
              transition: "none",
            }}
          />
        );
      })}

      {/* Gentle radial backlight */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          background: `radial-gradient(circle at 50% 35%, ${starOutlineColor}22 0%, transparent 65%)`,
          opacity: ambientBreathe,
          pointerEvents: "none",
          mixBlendMode: "screen",
          transition: "none",
        }}
      />

      {/* Camera Viewport Wrapper (Handles cinematic zoom centered on the title) */}
      <div
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          transform: `scale(${cameraScale})`,
          transformOrigin: "50% 35%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
        }}
      >
        {/* Title Container */}
        <div
          style={{
            position: "absolute",
            top: "35%",
            transform: `translateY(-50%) scale(${titleScale})`,
            opacity: titleFade,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            width: "100%",
            textAlign: "center",
            transition: "none",
          }}
        >
          <h1
            style={{
              fontFamily: antonFamily,
              fontSize: width * 0.055,
              fontWeight: 900,
              color: "#ffffff",
              margin: 0,
              padding: 0,
              textTransform: "uppercase",
              letterSpacing: `${titleTracking}em`,
              textShadow: "0 0 20px rgba(0,0,0,0.8)",
              transition: "none",
            }}
          >
            {titleText}
          </h1>
        </div>

        {/* Separator Flare Line */}
        <svg
          width={width * 0.45}
          height={height * 0.02}
          viewBox="0 0 500 20"
          style={{
            position: "absolute",
            left: "50%",
            top: "43%",
            transform: `translateX(-50%) scaleX(${separatorScaleX})`,
            opacity: separatorOpacity,
            overflow: "visible",
            transition: "none",
          }}
        >
          <defs>
            <linearGradient id="flareGrad" x1="0%" y1="0%" x2="100%" y2="0%">
              <stop offset="0%" stopColor="#ff4500" stopOpacity="0" />
              <stop offset="15%" stopColor="#ff4500" stopOpacity="0.4" />
              <stop offset="50%" stopColor="#ffea00" stopOpacity="1" />
              <stop offset="85%" stopColor="#ff4500" stopOpacity="0.4" />
              <stop offset="100%" stopColor="#ff4500" stopOpacity="0" />
            </linearGradient>
            <filter id="glow">
              <feGaussianBlur stdDeviation="4" result="coloredBlur" />
              <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>
          <path
            d="M 0,10 Q 250,0 500,10 Q 250,20 0,10 Z"
            fill="url(#flareGrad)"
            filter="url(#glow)"
          />
        </svg>

        {/* Connecting Timeline Line */}
        <div
          style={{
            position: "absolute",
            left: `${lineLeftPercent}%`,
            top: "65%",
            width: `${lineWidthPercent}%`,
            height: "2px",
            background: `linear-gradient(90deg, transparent, ${lineColor}aa 10%, ${lineColor}aa 90%, transparent)`,
            transform: `scaleX(${lineScaleX})`,
            transformOrigin: "left center",
            boxShadow: `0 0 8px ${lineColor}`,
            transition: "none",
          }}
        />

        {/* Sequential Stars & Glowing Halos */}
        {Array.from({ length: starCount }).map((_, i) => {
          // Calculate dynamically staggered entrance timings
          const starsStartFrame = Math.floor(totalFrames * 0.18);
          const starsEndFrame = Math.floor(totalFrames * 0.52);
          const starDelay = starCount > 1
            ? starsStartFrame + (i * (starsEndFrame - starsStartFrame)) / (starCount - 1)
            : starsStartFrame;

          const starAge = frame - starDelay;

          // Elastic "Pop" scale animation
          const starScale = interpolate(
            starAge,
            [0, 10, 18, 25],
            [0, 1.25, 0.95, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          // Kinetic Spin entrance
          const starRotate = interpolate(
            starAge,
            [0, 25],
            [540, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.bezier(0.16, 1, 0.3, 1),
            }
          );

          // Dynamic peak-glow during entry settle
          const starGlow = interpolate(
            starAge,
            [0, 10, 30],
            [0, 2.8, 1],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            }
          );

          // Horizontal coordinates distribution
          const xPercent = lineLeftPercent + (i * lineWidthPercent) / (starCount - 1);
          const starX = width * (xPercent / 100);

          // Star dimensions
          const outerRadius = width * 0.024;
          const innerRadius = width * 0.011;

          // Halo glow behind each star
          const glowOpacity = interpolate(
            starAge,
            [0, 10, 30],
            [0, 0.7, 0.22],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          const glowSize = interpolate(
            starAge,
            [0, 10, 30],
            [0, width * 0.1, width * 0.07],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <React.Fragment key={i}>
              {/* Radial glow background flare */}
              <div
                style={{
                  position: "absolute",
                  left: starX,
                  top: "65%",
                  width: glowSize,
                  height: glowSize,
                  transform: "translate(-50%, -50%)",
                  background: `radial-gradient(circle, ${starOutlineColor}bb 0%, transparent 70%)`,
                  opacity: glowOpacity,
                  pointerEvents: "none",
                  borderRadius: "50%",
                  mixBlendMode: "screen",
                  transition: "none",
                }}
              />

              {/* Precise Vector Star */}
              <div
                style={{
                  position: "absolute",
                  left: starX,
                  top: "65%",
                  transform: "translate(-50%, -50%)",
                  pointerEvents: "none",
                  transition: "none",
                }}
              >
                <Star
                  points={5}
                  innerRadius={innerRadius}
                  outerRadius={outerRadius}
                  fill={starColor}
                  stroke={starOutlineColor}
                  strokeWidth={4}
                  style={{
                    overflow: "visible",
                    transform: `scale(${starScale}) rotate(${starRotate}deg)`,
                    transformOrigin: "center",
                    transformBox: "fill-box",
                    filter: `drop-shadow(0 0 ${8 * starGlow}px ${starOutlineColor})`,
                    transition: "none",
                  }}
                />
              </div>
            </React.Fragment>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default InflectionPoints;